1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.section.clazz.Flow;
4	import net.officefloor.web.HttpHeaderParameter;
5	import org.springframework.samples.petclinic.rest.idempotency.IdempotencyStore;
6	
7	/**
8	 * First step of {@code POST /api/owners}: honours the optional {@code Idempotency-Key} header. When
9	 * the request carries a key already seen for a completed create, this is a repeat, so it takes the
10	 * {@code existing} branch (passing the originally created owner id) which responds with that owner and
11	 * 200 instead of creating a duplicate. Otherwise it takes the {@code proceed} branch into the normal
12	 * create pipeline; a request with no key always proceeds. The key is recorded once the create
13	 * succeeds (see {@link RecordIdempotency}).
14	 */
15	public class CheckIdempotency {
16	
17	    /** Continue into the normal create pipeline. */
18	    @FunctionalInterface
19	    public interface Proceed {
20	        void proceed();
21	    }
22	
23	    /** Short-circuit to the originally created owner, identified by its id. */
24	    @FunctionalInterface
25	    public interface Existing {
26	        void existing(Integer ownerId);
27	    }
28	
29	    public void service(@HttpHeaderParameter("Idempotency-Key") String idempotencyKey,
30	            IdempotencyStore store, @Flow("proceed") Proceed proceed, @Flow("existing") Existing existing) {
31	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
32	            Integer existingId = store.find(idempotencyKey);
33	            if (existingId != null) {
34	                existing.existing(existingId);
35	                return;
36	            }
37	        }
38	        proceed.proceed();
39	    }
40	}
