1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * The duplicate check for {@code POST /api/owners}, keyed on the household. The household id is now
11	 * deterministic — derived from the normalized lastName and postcode (see
12	 * {@link OwnerIdentity#deriveHouseholdId}) — so owners that share a lastName and postcode are the same
13	 * household. A second owner in an existing household is therefore rejected as a household duplicate
14	 * with 409, <em>unless</em> the request sets {@code sharesHousehold}, which bypasses this block and
15	 * lets the owner be created as a declared household member. On a match it throws
16	 * {@link DuplicateIdentityException}, handled globally as 409.
17	 */
18	public class EnsureIdentityUnique {
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws DuplicateIdentityException {
22	        // A declared household member is allowed to join an existing household, so it bypasses the
23	        // duplicate block entirely.
24	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
25	            return;
26	        }
27	
28	        String householdId = OwnerIdentity.deriveHouseholdId(
29	                OwnerIdentity.normalizeName(request.getLastName()), request.getPostcode());
30	        for (Owner existing : ownerRepository.findAll()) {
31	            // A soft-deleted owner no longer blocks a create.
32	            if (Boolean.TRUE.equals(existing.getDeleted())) {
33	                continue;
34	            }
35	            String existingHousehold = OwnerIdentity.deriveHouseholdId(
36	                    OwnerIdentity.normalizeName(existing.getLastName()), existing.getPostcode());
37	            if (householdId.equals(existingHousehold)) {
38	                throw new DuplicateIdentityException(householdId);
39	            }
40	        }
41	    }
42	}
