1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitException;
10	
11	/**
12	 * Rejects a create-owner request once the maximum number of owners
13	 * ({@link DailyOwnerLimitException#LIMIT}) have already been created on the same business day,
14	 * counted by {@link Owner#getRegistrationDate()}. The day counted is this request's <em>adjusted</em>
15	 * business day: the effective registration date — supplied in the request or defaulted to the server
16	 * date — rolled forward off a weekend or public holiday to the next non-holiday business day,
17	 * matching what {@link BuildOwner} will store.
18	 * Runs before {@link SaveOwner}, so the new owner is not yet counted; a business day already holding
19	 * 100 owners causes the 101st request to fail with 429.
20	 */
21	public class EnsureDailyOwnerLimit {
22	
23	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
24	            throws DailyOwnerLimitException {
25	        LocalDate effective = request.getRegistrationDate();
26	        if (effective == null) {
27	            effective = LocalDate.now();
28	        }
29	        LocalDate businessDay = BusinessDays.rollForward(effective);
30	        int count = 0;
31	        for (Owner existing : ownerRepository.findAll()) {
32	            if (businessDay.equals(existing.getRegistrationDate())) {
33	                count++;
34	            }
35	        }
36	        if (count >= DailyOwnerLimitException.LIMIT) {
37	            throw new DailyOwnerLimitException(businessDay, count);
38	        }
39	    }
40	}
